#include <iostream>
using namespace std;

void insertAt(int items[], int& size, int pos, int value) {
    for (int i = size; i > pos; i--) {
        items[i] = items[i - 1];
    }
    items[pos] = value;
    size++;
}

void removeAt(int items[], int& size, int pos) {
    for (int i = pos; i < size - 1; i++) {
        items[i] = items[i + 1];
    }
    size--;
}

void printItems(int items[], int size) {
    for (int i = 0; i < size; i++) {
        cout << items[i] << " ";
    }
    cout << endl;
}

int main() {
    int items[8] = {10, 20, 40, 50};
    int size = 4;
    insertAt(items, size, 2, 30);
    printItems(items, size);
    removeAt(items, size, 0);
    printItems(items, size);
    return 0;
}
